"use client"

import * as React from "react"
import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import {
  childItems,
  defineItem,
  Graph,
  GraphBody,
  isHost,
  listItems,
  paragraphsOf,
  textOf,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass as paletteTone,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type FlowTone = "default" | "accent" | "muted"

type FlowNode = {
  label: string
  tone?: FlowTone
  stretch?: boolean
}

type FlowRow = {
  nodes: FlowNode[]
}

type PathProps = {
  children?: React.ReactNode
}

type GraphFlowProps = {
  title: string
  /** Data form. Or write `<Path>` children. */
  rows?: FlowRow[]
  children?: React.ReactNode
  palette?: GraphPalette
  corner?: string
  className?: string
}

/**
 * One row of the flow. Markdown:
 *
 * ```mdx
 * <GraphFlow title="PUBLISH">
 *
 * write → review → **ship**
 *
 * </GraphFlow>
 * ```
 *
 * Split on `→` or `->`. Bold is the accent node, italic recedes.
 */
const Path = defineItem<PathProps>("Path")

const ARROW = /\s*(?:→|->|—>|=>)\s*/

function nodesOf(children: React.ReactNode): FlowNode[] {
  const nodes: FlowNode[] = []

  for (const child of React.Children.toArray(children)) {
    if (typeof child === "string" || typeof child === "number") {
      for (const part of String(child).split(ARROW)) {
        const label = part.trim()
        if (label) {
          nodes.push({ label })
        }
      }
      continue
    }

    if (!React.isValidElement<{ children?: React.ReactNode }>(child)) {
      continue
    }

    if (isHost(child, ["strong", "b"])) {
      nodes.push({ label: textOf(child).trim(), tone: "accent" })
      continue
    }

    if (isHost(child, ["em", "i"])) {
      nodes.push({ label: textOf(child).trim(), tone: "muted" })
      continue
    }

    nodes.push(...nodesOf(child.props.children))
  }

  return nodes
}

function rowsOf(children: React.ReactNode): FlowRow[] {
  const tagged = childItems(children, Path).map((path) => ({
    nodes: nodesOf(path.children),
  }))
  if (tagged.length > 0) {
    return tagged
  }

  const listed = listItems(children)
  if (listed.length > 0) {
    return listed.map((item) => ({
      nodes: nodesOf((item.props as { children?: React.ReactNode }).children),
    }))
  }

  const paragraphs = paragraphsOf(children)
  if (paragraphs.length > 0) {
    return paragraphs.map((paragraph) => ({
      nodes: nodesOf(
        (paragraph.props as { children?: React.ReactNode }).children
      ),
    }))
  }

  const text = textOf(children).trim()
  if (!text) {
    return []
  }

  return text.split(/\n+/).map((line) => ({ nodes: nodesOf(line) }))
}

function nodeTone(palette: GraphPalette | undefined): Record<FlowTone, string> {
  return {
    default: "text-foreground",
    accent: paletteTone(palette, "primary"),
    muted: paletteTone(palette, "secondary"),
  }
}

function GraphFlow({
  title,
  rows: rowsProp,
  children,
  palette,
  corner,
  className,
}: GraphFlowProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.08)
  const tones = nodeTone(palette)
  const rows = rowsProp ?? rowsOf(children)

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-7">
        <motion.div
          className="flex flex-col gap-7"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.5 }}
          whileInView="show"
        >
          {rows.map((row, rowIndex) => (
            <motion.div
              key={rowIndex}
              className="flex min-w-0 flex-wrap items-center gap-x-3 gap-y-2 sm:flex-nowrap"
              variants={item}
            >
              {row.nodes.map((node, nodeIndex) => {
                const tone = node.tone ?? "default"
                const live = tone === "accent"

                return (
                  <div
                    key={`${node.label}-${nodeIndex}`}
                    className={cn(
                      "flex min-w-0 items-center gap-3",
                      node.stretch && "min-w-16 flex-1"
                    )}
                  >
                    {nodeIndex > 0 ? (
                      <GraphArrow accent={live} stretch={node.stretch} />
                    ) : null}
                    <span
                      className={cn("shrink-0 whitespace-nowrap", tones[tone])}
                    >
                      {node.label}
                    </span>
                  </div>
                )
              })}
            </motion.div>
          ))}
        </motion.div>
      </GraphBody>
    </Graph>
  )
}

export { GraphFlow, Path }
export type { FlowNode, FlowRow, GraphFlowProps, PathProps }

"use client"

import type { ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"

import { GraphArrow } from "@/registry/default/graph-frame/graph-arrow"
import {
  childItems,
  defineItem,
  Graph,
  GraphBody,
  hasHost,
  itemText,
  listItems,
  numbers,
  splitLabel,
  textOf,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fillDelay,
  graphTransition,
  toneClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type BarSeries = {
  label: string
  values: number[]
  size?: "sm" | "lg"
}

type SeriesProps = {
  label: string
  values?: number[] | string
  size?: "sm" | "lg"
}

/** `<Series label="before">2 4 3 5 2</Series>` — first is from, second is to. */
const Series = defineItem<SeriesProps>("Series")

type GraphBarsProps = {
  title: string
  /** Left series. Or write two `<Series>` children. */
  from?: BarSeries
  /** Right series. Or write two `<Series>` children. */
  to?: BarSeries
  children?: ReactNode
  processor?: string
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function MiniBars({
  values,
  height,
  delay = 0,
  tone = "accent",
  fill,
  palette,
}: {
  values: number[]
  height: number
  delay?: number
  tone?: "accent" | "muted"
  fill: string
  palette?: GraphPalette
}) {
  const reduce = useReducedMotion()
  const max = Math.max(...values, 1)

  return (
    <div className="flex items-end gap-1">
      {values.map((value, index) => {
        const level = Math.round((value / max) * (height - 1))

        return (
          <span className="flex w-[1ch] flex-col justify-end" key={index}>
            {Array.from({ length: height }, (_, row) => {
              const fromBottom = height - 1 - row
              const on = fromBottom <= level

              return (
                <motion.span
                  className={cn(
                    "h-[1em] w-full text-center",
                    on
                      ? tone === "accent"
                        ? toneClass(palette, "primary")
                        : toneClass(palette, "secondary")
                      : "text-transparent"
                  )}
                  initial={reduce || !on ? false : { opacity: 0 }}
                  key={row}
                  transition={graphTransition(reduce, {
                    delay: delay + fillDelay(reduce, index, 0.03),
                  })}
                  viewport={{ once: true }}
                  whileInView={{ opacity: 1 }}
                >
                  {on ? fill : " "}
                </motion.span>
              )
            })}
          </span>
        )
      })}
    </div>
  )
}

function GraphBars({
  title,
  from: fromProp,
  to: toProp,
  children,
  processor,
  glyphs,
  palette,
  corner,
  className,
}: GraphBarsProps) {
  const listed = listItems(children).map((item) => {
    const { label, rest } = splitLabel(itemText(item))
    const content = (item.props as { children?: ReactNode }).children
    return {
      label: label || itemText(item),
      values: numbers(rest),
      size: hasHost(content, ["strong", "b"]) ? ("lg" as const) : undefined,
    }
  })
  const tagged = childItems(children, Series).map((entry) => ({
    label: entry.label,
    values: numbers(entry.values ?? textOf(entry.children)),
    size: entry.size,
  }))
  const series = listed.length > 0 ? listed : tagged
  const empty: BarSeries = { label: "", values: [] }
  const from = fromProp ?? series[0] ?? empty
  const to = toProp ?? series[1] ?? empty
  const marks = trackMarks(glyphs)
  const fromHeight = from.size === "lg" ? 8 : 5
  const toHeight = to.size === "lg" ? 8 : 5

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody>
        <div className="flex flex-col items-center gap-8 sm:flex-row sm:items-end sm:justify-center sm:gap-8">
          <div className="flex flex-col items-center gap-3">
            <MiniBars
              delay={0.04}
              fill={marks.fill}
              height={fromHeight}
              palette={palette}
              tone="muted"
              values={from.values}
            />
            <p className={toneClass(palette, "secondary")}>{from.label}</p>
          </div>

          <div className="flex items-center justify-center gap-3 text-graph-muted max-sm:rotate-90">
            <GraphArrow />
            {processor ? <span>{processor}</span> : null}
            <GraphArrow />
          </div>

          <div className="flex flex-col items-center gap-3">
            <MiniBars
              delay={0.16}
              fill={marks.fill}
              height={toHeight}
              palette={palette}
              values={to.values}
            />
            <p className="text-foreground">{to.label}</p>
          </div>
        </div>
      </GraphBody>
    </Graph>
  )
}

export { GraphBars, Series }
export type { BarSeries, GraphBarsProps, SeriesProps }

"use client"

import type { ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"

import {
  childItems,
  defineItem,
  firstToken,
  Graph,
  GraphBody,
  GraphTick,
  GraphTrack,
  itemText,
  listItems,
  numberOf,
  textOf,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fadeUp,
  staggerList,
  toneClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"

type RankItem = {
  /** Falls back to the child text: `<Rank value={12400}>/docs</Rank>`. */
  label?: string
  value: number | string
  display?: string
}

type GraphRankProps = {
  title: string
  /** Data form. Or write `<Rank />` children. */
  items?: RankItem[]
  children?: ReactNode
  max?: number
  ticks?: number
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

/** `<Rank value={4100}>/install</Rank>` inside `<GraphRank>`. */
const Rank = defineItem<RankItem>("Rank")

type RankRow = { label: string; value: number; display?: string }

function formatValue(item: RankRow) {
  if (item.display) {
    return item.display
  }

  return item.value.toLocaleString("en-US", {
    maximumFractionDigits: Number.isInteger(item.value) ? 0 : 1,
  })
}

function GraphRank({
  title,
  items: itemsProp,
  children,
  max,
  ticks = 20,
  glyphs,
  palette,
  corner,
  className,
}: GraphRankProps) {
  const reduce = useReducedMotion()
  const item = fadeUp(reduce)
  const list = staggerList(reduce, 0.05)
  const listed = listItems(children).map((item) => {
    const { token, rest } = firstToken(itemText(item))
    return {
      display: token,
      value: numberOf(token),
      label: rest,
    }
  })
  const tagged = childItems(children, Rank).map((entry) => ({
    ...entry,
    label: entry.label ?? textOf(entry.children),
  }))
  const items: RankRow[] = (
    itemsProp ?? (listed.length > 0 ? listed : tagged)
  ).map((entry) => ({
    label: entry.label ?? "",
    value: numberOf(entry.value),
    display: entry.display,
  }))
  const peak = max ?? Math.max(...items.map((entry) => entry.value), 1)
  const marks = trackMarks(glyphs, {
    empty: "-",
    rest: "=",
    fill: "=",
  })

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody className="flex flex-col gap-3">
        <motion.ol
          className="flex w-full list-none flex-col gap-2"
          initial={reduce ? false : "hidden"}
          variants={list}
          viewport={{ once: true, amount: 0.4 }}
          whileInView="show"
        >
          {items.map((entry) => {
            const filled = Math.min(
              ticks,
              Math.round((Math.max(entry.value, 0) / peak) * ticks)
            )
            const shown = formatValue(entry)

            return (
              <motion.li
                aria-label={`${entry.label} ${shown}`}
                className="grid grid-cols-[minmax(0,7rem)_minmax(0,1fr)_minmax(0,7rem)] items-center gap-x-2 sm:gap-x-4"
                key={entry.label}
                variants={item}
              >
                <span className="truncate text-foreground">{entry.label}</span>
                <span className="flex min-w-0 items-center">
                  <span
                    aria-hidden="true"
                    className="text-graph-frame select-none"
                  >
                    [
                  </span>
                  <GraphTrack>
                    {Array.from({ length: ticks }, (_, index) => {
                      const on = index < filled

                      return (
                        <GraphTick
                          className={
                            on
                              ? toneClass(palette, "primary")
                              : "text-graph-frame"
                          }
                          key={index}
                        >
                          {on ? marks.fill : marks.empty}
                        </GraphTick>
                      )
                    })}
                  </GraphTrack>
                  <span
                    aria-hidden="true"
                    className="text-graph-frame select-none"
                  >
                    ]
                  </span>
                </span>
                <span className="text-right text-graph-muted tabular-nums">
                  {shown}
                </span>
              </motion.li>
            )
          })}
        </motion.ol>
      </GraphBody>
    </Graph>
  )
}

export { GraphRank, Rank }
export type { GraphRankProps, RankItem }

"use client"

import type { ReactNode } from "react"
import { motion, useReducedMotion } from "motion/react"

import {
  childElements,
  childItems,
  defineItem,
  Graph,
  GraphBody,
  itemText,
  linesOf,
  listItems,
  splitLabel,
  textOf,
} from "@/registry/default/graph-frame/graph-frame"
import {
  fillDelay,
  graphTransition,
  isMonoPalette,
  seriesClass,
  trackMarks,
  type Glyphs,
  type GraphPalette,
} from "@/registry/default/graph-frame/graph-motion"
import { cn } from "@/lib/utils"

type CellGrid = {
  label: string
  cells: number[][]
}

type GridProps = {
  label: string
  cells?: number[][]
}

/** `<Grid label="fragments">1 0 1 0 0\n0 1 0 1 0</Grid>` */
const Grid = defineItem<GridProps>("Grid")

type GraphCellsProps = {
  title: string
  /** Data form. Or write `<Grid>` children. */
  items?: CellGrid[]
  children?: ReactNode
  glyphs?: Glyphs
  palette?: GraphPalette
  corner?: string
  className?: string
}

function parseRow(line: string): number[] {
  return line
    .split(/[\s,]+/)
    .filter(Boolean)
    .map(Number)
    .filter((value) => Number.isFinite(value))
}

function gridCells(node: ReactNode): number[][] {
  const blocks = childElements(node)
  if (blocks.length > 1) {
    return blocks
      .map((block) => parseRow(textOf(block.element)))
      .filter((row) => row.length > 0)
  }

  const text = textOf(node).trim()
  if (text.includes("/")) {
    return text
      .split("/")
      .map(parseRow)
      .filter((row) => row.length > 0)
  }

  return linesOf(node)
    .map(parseRow)
    .filter((row) => row.length > 0)
}

function GraphCells({
  title,
  items: itemsProp,
  children,
  glyphs,
  palette,
  corner,
  className,
}: GraphCellsProps) {
  const listed = listItems(children).map((item) => {
    const { label, rest } = splitLabel(itemText(item))
    return {
      label,
      cells: gridCells(rest),
    }
  })
  const tagged = childItems(children, Grid).map((entry) => ({
    label: entry.label,
    cells: entry.cells ?? gridCells(entry.children),
  }))
  const items = itemsProp ?? (listed.length > 0 ? listed : tagged)
  const reduce = useReducedMotion()
  const marks = trackMarks(glyphs, {
    empty: "·",
    rest: "░",
    fill: "█",
  })

  return (
    <Graph title={title} className={className} corner={corner}>
      <GraphBody>
        <div className="@container flex flex-col items-center gap-10 @min-[28rem]:flex-row @min-[28rem]:justify-center @min-[28rem]:gap-12">
          {items.map((item, itemIndex) => (
            <div className="flex flex-col items-center gap-4" key={item.label}>
              <div aria-hidden="true" className="flex flex-col gap-1">
                {item.cells.map((row, rowIndex) => (
                  <div className="flex gap-1" key={rowIndex}>
                    {row.map((cell, cellIndex) => {
                      const filled = cell === 1

                      return (
                        <motion.span
                          className={cn(
                            "w-[1ch] text-center select-none",
                            filled
                              ? isMonoPalette(palette)
                                ? "text-graph-accent"
                                : seriesClass(palette, itemIndex)
                              : "text-graph-frame"
                          )}
                          initial={reduce || !filled ? false : { opacity: 0 }}
                          key={cellIndex}
                          transition={graphTransition(reduce, {
                            delay: fillDelay(
                              reduce,
                              itemIndex * 8 + rowIndex * 5 + cellIndex
                            ),
                          })}
                          viewport={{ once: true }}
                          whileInView={{ opacity: 1 }}
                        >
                          {filled ? marks.fill : marks.empty}
                        </motion.span>
                      )
                    })}
                  </div>
                ))}
              </div>
              <p
                className={
                  isMonoPalette(palette)
                    ? "text-graph-muted"
                    : seriesClass(palette, itemIndex)
                }
              >
                {item.label}
              </p>
            </div>
          ))}
        </div>
      </GraphBody>
    </Graph>
  )
}

